ALTER TABLE archive_drafts DROP CHECK chk_archive_drafts_status, DROP CHECK chk_archive_drafts_deidentification_status;
-- statement-break
ALTER TABLE archive_drafts ADD COLUMN deidentified_by_user_id VARCHAR(36) NULL, ADD COLUMN deidentified_at VARCHAR(40) NULL, ADD COLUMN deidentification_reason TEXT NULL, ADD COLUMN reviewed_by_user_id VARCHAR(36) NULL, ADD COLUMN reviewed_at VARCHAR(40) NULL, ADD COLUMN review_reason TEXT NULL, ADD COLUMN version INT NOT NULL DEFAULT 1, ADD COLUMN usage_scope VARCHAR(32) NOT NULL DEFAULT 'internal_archive', ADD COLUMN retention_status VARCHAR(32) NOT NULL DEFAULT 'retained', ADD CONSTRAINT chk_archive_drafts_status CHECK (status IN ('draft', 'pending_review', 'published', 'rejected', 'withdrawn')), ADD CONSTRAINT chk_archive_drafts_deidentification_status CHECK (deidentification_status IN ('manual_review_required', 'deidentified', 'rejected')), ADD CONSTRAINT chk_archive_drafts_version CHECK (version >= 1), ADD CONSTRAINT chk_archive_drafts_usage_scope CHECK (usage_scope IN ('internal_archive', 'learning_resource')), ADD CONSTRAINT chk_archive_drafts_retention_status CHECK (retention_status IN ('retained', 'withdrawn')), ADD CONSTRAINT chk_archive_drafts_publication_state CHECK ((status <> 'published' OR (deidentification_status = 'deidentified' AND usage_scope = 'learning_resource' AND retention_status = 'retained')) AND (status <> 'withdrawn' OR (usage_scope = 'internal_archive' AND retention_status = 'withdrawn'))), ADD CONSTRAINT fk_archive_drafts_deidentifier FOREIGN KEY (deidentified_by_user_id) REFERENCES users(id) ON DELETE RESTRICT, ADD CONSTRAINT fk_archive_drafts_reviewer FOREIGN KEY (reviewed_by_user_id) REFERENCES users(id) ON DELETE RESTRICT;
-- statement-break
CREATE INDEX idx_archive_drafts_status ON archive_drafts(status, updated_at);
